using System;
using System.Linq;
using System.Collections.Generic;
namespace F1Manager {
public static class Patch25Tests {
    static Career Race(uint seed,int round=0){var s=Data.Create(0,"",seed);s.Round=round;s.Stage=Engine.Sessions(s).Length-1;Engine.PrepareWeekend(s);s.Weekend.Weather="Сухо";s.Weekend.Qual=s.People.Where(p=>p.Kind==0&&!p.Retired&&p.Deal!=null).OrderByDescending(p=>p.Rating).Select(p=>p.Id).ToList();Engine.Start(s);s.Weekend.Live.WeatherAt=double.MaxValue;return s;}
    public static void Run(Action<bool,string> check,Action<Action,string> rejects){
        foreach(var p in Data.Parts){var options=CarModel.FocusOptions(p.Key);var balanced=CarModel.Effects(p.Key,p.Gain,"balanced");check(balanced.SequenceEqual(CarModel.Effects(p.Key,p.Gain))&&options.Length==3&&options.Skip(1).All(f=>!CarModel.Effects(p.Key,p.Gain,f).SequenceEqual(balanced)),"2.5 development directions change the effect vector: "+p.Key);}
        var down=CarModel.Effects("floor",5,"downforce");var speed=CarModel.Effects("floor",5,"speed");check(down[0]>speed[0]&&down[4]<speed[4],"2.5 downforce and speed impose actual aerodynamic tradeoffs");
        var focus=Data.Create(0,"",2501);Engine.Develop(focus,"floor",5,false,"speed");var team=Engine.Team(focus,0);var project=team.Projects.Single();check(project.Focus=="speed","2.5 project records selected development focus");project.Failure=0;Engine.Advance(focus,project.Due);var part=team.Parts.Single();check(part.TraitBonus!=null&&part.TraitBonus.SequenceEqual(CarModel.Effects("floor",part.Bonus,"speed")),"2.5 delivered part installs focused multi-factor gains");var loaded=Engine.Deserialize(Engine.Serialize(focus));check(CarModel.Values(Engine.Team(loaded,0)).SequenceEqual(CarModel.Values(team))&&Engine.Team(loaded,0).Parts.Single().TraitBonus.SequenceEqual(part.TraitBonus),"2.5 focused gains survive save and reload");
        var future=Data.Create(0,"",2509);var futureTeam=future.Teams[0];var focused=new Installed{Key="floor",Bonus=4,TraitBonus=CarModel.Effects("floor",4,"speed")};futureTeam.Parts.Add(focused);var prepared=new Installed{Key="floor",Bonus=2,TraitBonus=CarModel.Effects("floor",2,"downforce")};futureTeam.NextParts.Add(prepared);var expected=focused.TraitBonus.Select((v,i)=>v*Research.Carryover+prepared.TraitBonus[i]).ToArray();future.SeasonDone=true;Engine.NextSeason(future);check(focused.TraitBonus.Zip(expected,(a,b)=>Math.Abs(a-b)<.00000001).All(x=>x),"2.5 focused current gains decay while future focused gains transfer at full effect");
        var legacy=Race(2508);var legacyLive=legacy.Weekend.Live;legacyLive.TickRace=false;legacyLive.Elapsed=900;for(int i=0;i<legacyLive.Entries.Count;i++){var e=legacyLive.Entries[i];e.Lap=10;e.LapDuration=90;e.Remaining=10+i*2;}var legacyOrder=Engine.Order(legacy).Select(e=>e.Id).ToArray();RaceDirector.MigrateLive(legacy);check(Engine.Order(legacy).Select(e=>e.Id).SequenceEqual(legacyOrder)&&legacyLive.Entries.All(e=>e.Lap==10)&&legacyLive.Elapsed==900,"2.5 legacy live race migration preserves order, completed laps and elapsed time");check(legacyLive.Entries.All(e=>e.RaceTime>=900)&&legacyLive.Entries.Select(e=>e.RaceTime).Distinct().Count()==legacyLive.Entries.Count,"2.5 legacy partial-lap progress becomes consistent gaps rather than zeroing the field");
        var old=Data.Create(0,"",2502);old.Version=5;foreach(var t in old.Teams)t.PowerCars=null;old.Teams[0].Parts.Add(new Installed{Key="rear",Bonus=3});var values=CarModel.Values(old.Teams[0]);uint seed=old.Seed;var migrated=Engine.Deserialize(Engine.Serialize(old));check(migrated.Version==8&&migrated.Seed==seed&&CarModel.Values(migrated.Teams[0]).SequenceEqual(values)&&migrated.Teams.All(t=>t.PowerCars.Count==2),"2.5 schema 5 migration preserves car performance and seed and initializes all power units");
        var unit=Data.Create(0,"",2503);var car=Powertrain.Car(unit.Teams[0],0);double cash=unit.Cash;Powertrain.Replace(unit,0,0);check(car.Used[0]==2&&unit.Cash==cash&&!car.GridPenalty,"2.5 an in-allowance component has no charge or penalty");while(car.Used[0]<Powertrain.Limits[0])Powertrain.Replace(unit,0,0);Powertrain.Replace(unit,0,0);check(unit.Cash==cash-8&&car.GridPenalty&&car.Used[0]==5,"2.5 fifth ICE charges eight million and queues a grid penalty");check(Powertrain.Car(unit.Teams[0],1).Used[0]==1,"2.5 component allocation is independent for each machine");
        unit.Stage=6;Engine.PrepareWeekend(unit);unit.Weekend.Qual=unit.People.Where(p=>p.Kind==0&&p.Deal!=null).OrderBy(p=>p.Id).Select(p=>p.Id).ToList();Engine.Start(unit);check(Engine.Order(unit).Last().Id==0&&!car.GridPenalty,"2.5 grid penalty moves affected driver to the back exactly once");rejects(()=>Powertrain.Replace(unit,0,0),"2.5 active session blocks component replacement");
        var sprint=Data.Create(0,"",2510);sprint.Round=1;sprint.Stage=4;Powertrain.Car(sprint.Teams[0],0).GridPenalty=true;Engine.Start(sprint);check(Powertrain.Car(sprint.Teams[0],0).GridPenalty,"2.5 a sprint does not consume a next-Grand-Prix grid penalty");
        var wear=Race(2504);var entry=wear.Weekend.Live.Entries.First(e=>e.Team==0);var pc=Powertrain.Car(wear,entry);entry.EngineMode=2;entry.DrivingMode=2;Powertrain.Wear(wear,entry,20);var attacked=pc.Condition.ToArray();pc.Condition=new double[]{100,100,100};entry.EngineMode=0;entry.DrivingMode=0;Powertrain.Wear(wear,entry,20);check(pc.Condition.Zip(attacked,(a,b)=>a>b).All(x=>x)&&attacked.Distinct().Count()==3,"2.5 attack wears ICE, ERS and gearbox differently and faster than conserve");pc.Condition[0]=10;check(Powertrain.PaceLoss(wear,entry)>1,"2.5 low engine condition costs lap time");pc.Condition[0]=0;RaceDirector.Step(wear,true);check(entry.Dnf&&entry.Reason.Contains("ДВС"),"2.5 exhausted component causes a specific mechanical retirement");
        check(RaceDirector.TicksFor(Data.Tracks[5])==1&&RaceDirector.TicksFor(Data.Tracks[0])==2&&RaceDirector.TicksFor(Data.Tracks[12])==3,"2.5 Monaco, medium and passing circuits use one, two and three sector ticks per lap");
        foreach(int round in new[]{5,0,12}){var s=Race(2511+(uint)round,round);var l=s.Weekend.Live;for(int i=0;i<l.TicksPerLap-1;i++)RaceDirector.Step(s,true);check(l.Entries.Where(e=>!e.Dnf).All(e=>e.Lap==0),"2.5 no premature lap completion on circuit "+round);RaceDirector.Step(s,true);check(l.Entries.Where(e=>!e.Dnf).All(e=>e.Lap==1),"2.5 the final sector tick completes one lap on circuit "+round);}
        var stable=Race(2520,5);var live=stable.Weekend.Live;var initial=Engine.Order(stable).Select(e=>e.Id).ToArray();for(int i=0;i<live.Entries.Count;i++){var e=Engine.Order(stable)[i];e.RaceTime=i*20;e.EngineMode=1;e.DrivingMode=1;}RaceDirector.Step(stable,true);check(Engine.Order(stable).Select(e=>e.Id).SequenceEqual(initial),"2.5 well-separated drivers retain positions instead of random reshuffling");var own=live.Entries.First(e=>e.Team==0);double fresh=RaceDirector.Pace(stable,own);own.TyreWear=95;double worn=RaceDirector.Pace(stable,own);check(worn>fresh+4,"2.5 actual tyre wear materially reduces pace");own.TyreWear=20;Powertrain.SetModes(stable,own.Id,2,2);check(own.EngineMode==2&&own.DrivingMode==2,"2.5 live engine and driving modes are separate controls");rejects(()=>Powertrain.SetModes(stable,own.Id,3,1),"2.5 invalid race mode is rejected");rejects(()=>Powertrain.SetModes(stable,live.Entries.First(e=>e.Team!=0).Id,2,2),"2.5 player cannot control another team's modes");
        Engine.Pit(stable,own.Id,"H");RaceDirector.Step(stable,true);check(own.Stops==1&&own.Tyre=="H"&&own.TyreWear==0&&!own.PitRequested,"2.5 manual pit command changes tyres and resets wear on the next tick");check(own.ScheduledStops==0,"2.5 early manual stop does not erase a later scheduled stop");
        foreach(string flag in new[]{"SC","VSC","RED"}){RaceDirector.Event(stable,flag,"Test "+flag,2);int ticks=live.RaceTick;double time=live.Elapsed;RaceDirector.Step(stable);check(live.RaceTick==ticks&&live.Elapsed==time&&live.AwaitingEvent,"2.5 "+flag+" pauses race progress until player decision");var state=Engine.Deserialize(Engine.Serialize(stable));check(state.Weekend.Live.Flag==flag&&state.Weekend.Live.AwaitingEvent&&state.Weekend.Live.RaceTick==ticks,"2.5 "+flag+" and decision survive saving");RaceDirector.Continue(stable);RaceDirector.Step(stable,true);check(flag=="RED"?live.Flag=="SC":live.RaceTick==ticks+1,"2.5 "+flag+" resumes after a decision");}
        live.Flag="SC";live.FlagTicks=20;live.AwaitingEvent=false;live.Paused=false;var beforeSC=Engine.Order(stable).Select(e=>e.Id).ToArray();RaceDirector.Step(stable,true);check(Engine.Order(stable).Select(e=>e.Id).SequenceEqual(beforeSC),"2.5 safety-car running forbids on-track overtaking");
        var resume=Engine.Deserialize(Engine.Serialize(stable));resume.Weekend.Live.Paused=false;RaceDirector.Step(stable,true);RaceDirector.Step(resume,true);check(stable.Seed==resume.Seed&&stable.Weekend.Live.RaceTick==resume.Weekend.Live.RaceTick&&Engine.Order(stable).Select(e=>e.Id).SequenceEqual(Engine.Order(resume).Select(e=>e.Id))&&stable.Weekend.Live.Entries.All(e=>Math.Abs(e.RaceTime-resume.Weekend.Live.Entries.First(x=>x.Id==e.Id).RaceTime)<.00000001)&&stable.Teams.All(t=>t.PowerCars.All(c=>c.Condition.Zip(Powertrain.Car(Engine.Team(resume,t.Id),c.Seat).Condition,(a,b)=>Math.Abs(a-b)<.00000001).All(x=>x))),"2.5 resumed tick produces the same deterministic result including resources and gaps");
        var finish=Race(2540);var running=finish.Weekend.Live;Engine.SimulateSession(finish);int count=finish.Archive.Count,points=finish.Teams.Sum(t=>t.Points);RaceDirector.Step(finish,true);check(count==1&&finish.Archive.Count==count&&finish.Teams.Sum(t=>t.Points)==points&&running.Finished,"2.5 race completion archives and awards points once");check(finish.Archive[0].Sessions.Last().Rows.Where(r=>!r.Dnf).Select(r=>r.Time).SequenceEqual(finish.Archive[0].Sessions.Last().Rows.Where(r=>!r.Dnf).Select(r=>r.Time).OrderBy(t=>t)),"2.5 finish times follow the authoritative race order");
        Powertrain.Reset(team);check(team.PowerCars.All(c=>c.Used.SequenceEqual(new[]{1,1,1})&&c.Condition.All(x=>x==100)&&!c.GridPenalty),"2.5 new-season inventories reset all three allocations for both cars");
        var bad=Engine.Deserialize(Engine.Serialize(focus));bad.Teams[0].PowerCars[0].Condition[0]=double.NaN;rejects(()=>Engine.Validate(bad),"2.5 invalid component condition is rejected");
    }
